const rawContent = $input.item.json.message.content;
let parsed;

try {
  parsed = JSON.parse(rawContent);
} catch (error) {
  // Fallback if Ollama returns invalid JSON
  parsed = {
    reply: "Thank you for your message. We are having a temporary technical issue. A team member will review your request.",
    lead_ready: false,
    human_handoff: true,
    handoff_reason: "invalid_ai_json",
    lead_score: 0,
    lead: {}
  };
}

return {
  json: parsed
};

